fn read_and_parse_note(file: &ImportFile) -> Result<ParsedNote, String> {
    let raw = fs::read_to_string(&file.path).map_err(|err| err.to_string())?;
    let is_html = matches!(extension_lower(&file.path).as_deref(), Some("html" | "htm"));

